function neetMonthlyTrend(people) {
	const months = [
		"Март",
		"Апрель",
		"Май",
		"Июнь",
		"Июль",
		"Август"
	];
	const total = people.filter((p) => p.neet).length;
	return months.map((m, i) => ({
		month: m,
		neet: Math.round(total * (1.22 - i * .04) + i * 7 % 5)
	}));
}
